INSERT INTO stage_events (qid, title, summary, start_year, start_month, start_day, end_year, end_month, end_day, precision, display_date, importance, url) VALUES
  ('Q2453421', 'Battle of Rastarkalv', 'The Battle of Rastarkalv (Norwegian: Slaget på Rastarkalv) took place in 955 on the southern part of the island of Frei in the present-day Kristiansund Municipality in Møre og Romsdal county, Norway. This was one of several battles between the forces of King Haakon the Good and those of the sons of Eirik Bloodaxe (Eiriksønnene).', 955, NULL, NULL, NULL, NULL, NULL, 'year', '955', 37, 'https://en.wikipedia.org/wiki/Battle_of_Rastarkalv'),
  ('Q738768', 'Battle of Fitjar', 'The Battle of Fitjar (Norwegian: Slaget ved Fitjar på Stord) took place in 961 in Fitjar on the island Stord in the county of Hordaland, Norway.', 961, NULL, NULL, NULL, NULL, NULL, 'year', '961', 48, 'https://en.wikipedia.org/wiki/Battle_of_Fitjar'),
  ('Q1267571', 'Battle of Hjörungavágr', 'The Battle of Hjǫrungavágr (Norwegian: Slaget ved Hjørungavåg) is a semi-legendary naval battle that took place in the late 10th century between the Jarls of Lade and a Danish invasion fleet led by the fabled Jomsvikings. This battle played an important role in the struggle by Haakon Sigurdsson (c.', 984, NULL, NULL, NULL, NULL, NULL, 'year', '984', 53, 'https://en.wikipedia.org/wiki/Battle_of_Hj%C3%B6rungav%C3%A1gr'),
  ('Q1163186', 'Battle of Svolder', 'The Battle of Svolder (also referred to as Svold or Swold) was a large naval battle during the Viking age, fought in September 1000 in the western Baltic Sea between King Olaf of Norway and an alliance of the Kings of Denmark and Sweden and Olaf''s enemies in Norway. The backdrop of the battle was the unification of Norway into a single independent state after longstanding Danish efforts to control the country, combined with the spread of Christianity in Scandinavia.', 999, NULL, NULL, NULL, NULL, NULL, 'year', '999', 65, 'https://en.wikipedia.org/wiki/Battle_of_Svolder'),
  ('Q1288012', 'Battle of Nesjar', 'Battle of Nesjar (Slaget ved Nesjar) was a sea battle off the coast of Norway in 1016. It was a primary event in the reign of King Olav Haraldsson (later Saint Olav).', 1016, NULL, NULL, NULL, NULL, NULL, 'year', '1016', 47, 'https://en.wikipedia.org/wiki/Battle_of_Nesjar'),
  ('Q499768', 'Battle of Helgeå', 'The Battle of Helgeå (Norwegian: Slaget ved Helgeå, Swedish: Slaget vid Helgeå), or Battle of the Holy River, was a naval engagement that took place in 1026 between joint Danish and English forces and a combined Norwegian and Swedish force, at the estuary of a river called Helge (Holy River) in Denmark or Sweden. King Olaf II of Norway and King Anund Jacob of Sweden took advantage of the commitment of Danish King Cnut in England and began to launch attacks on the Danish in the Baltic Sea.', 1026, NULL, NULL, NULL, NULL, NULL, 'year', '1026', 50, 'https://en.wikipedia.org/wiki/Battle_of_Helge%C3%A5'),
  ('Q830878', 'Battle of Stiklestad', 'The Battle of Stiklestad (Norwegian: Slaget på Stiklestad; Old Norse: Stiklastaðaorrusta) in 1030 is one of the most famous battles in the history of Norway. In this battle, King Olaf II of Norway was killed.', 1030, 7, 29, NULL, NULL, NULL, 'day', '29 July 1030', 63, 'https://en.wikipedia.org/wiki/Battle_of_Stiklestad'),
  ('Q3353388', 'Battle of Niså', 'The Battle of Niså (Slaget ved Niså) was a naval battle fought on 9 August 1062 between the forces of Norwegian king Harald Hardrada and king Sweyn II of Denmark. Harald had claimed the Danish throne since 1047, and had launched raids into Denmark ever since.', 1062, 8, 9, NULL, NULL, NULL, 'day', '9 August 1062', 47, 'https://en.wikipedia.org/wiki/Battle_of_Nis%C3%A5'),
  ('Q10671364', 'Battle of Holmengrå', 'The Battle of Holmengrå (Norwegian: Slaget ved Holmengrå) was a naval battle fought on 12 November 1139 near the island Holmengrå south of Hvaler, between the forces of the child kings Sigurd Haraldsson and Inge Haraldsson on the one side, and on the other side the pretender Sigurd Slembe and his ally King Magnus the Blind (by Sigurd''s claim his nephew). Inge and Sigurd Haraldsson were sons of the previous king Harald Gille, who had been killed by Sigurd Slembe in 1136.', 1139, 11, 12, NULL, NULL, NULL, 'day', '12 November 1139', 34, 'https://en.wikipedia.org/wiki/Battle_of_Holmengr%C3%A5'),
  ('Q653707', 'Fimreite', 'The Battle of Fimreite (Norwegian: Slaget ved Fimreite) was a naval battle fought on June 15, 1184, between King Magnus Erlingsson and the Birkebeiner supported Sverre Sigurdsson. At this time in Norwegian history it was extremely common for there to be changes in leadership, and political coups were often conducted to establish a new ruler.', 1184, 6, 15, NULL, NULL, NULL, 'day', '15 June 1184', 43, 'https://en.wikipedia.org/wiki/Battle_of_Fimreite'),
  ('Q2097266', 'Battle of Largs', 'The Battle of Largs (2 October 1263) was a battle between the kingdoms of Norway and Scotland, on the Firth of Clyde near Largs, Scotland. The conflict formed part of the Norwegian expedition against Scotland in 1263, in which Haakon Haakonsson, King of Norway attempted to reassert Norwegian sovereignty over the western seaboard of Scotland.', 1263, 10, 2, NULL, NULL, NULL, 'day', '2 October 1263', 53, 'https://en.wikipedia.org/wiki/Battle_of_Largs'),
  ('Q2619606', 'Treaty of Novgorod', 'The Treaty of Novgorod (Russian: Новгородско-норвежский договор, romanized: Novgorodsko-norvezhskiy dogovor; Norwegian: Novgorod-traktaten) was a 10-year peace treaty signed on 3 June 1326 in Novgorod. It marked the end of decades of border skirmishes between Norway and Novgorod in the far northern region of Finnmark.', 1326, NULL, NULL, NULL, NULL, NULL, 'year', '1326', 50, 'https://en.wikipedia.org/wiki/Treaty_of_Novgorod_(1326)'),
  ('Q823916', 'Dutch–Hanseatic War', 'The Dutch–Hanseatic War was a conflict between the County of Holland, acting independently of the rest of the Burgundian Netherlands of which it formed part, and the Hanseatic League. It led to little actual fighting, with a Dutch fleet patrolling Øresund while a Hanseatic fleet blocked their access to the Baltic Sea.', 1438, NULL, NULL, 1441, NULL, NULL, 'year', '1438–1441', 41, 'https://en.wikipedia.org/wiki/Dutch%E2%80%93Hanseatic_War'),
  ('Q17750244', 'Treaty of Bergen', 'Treaty of Bergen, signed on 29 August 1450 in Bergen, between Norway and Denmark. The agreement was in many ways a continuation of the Kalmar Union founded in 1397, between Norway, Denmark and Sweden, while Norway and Denmark had been in a personal union with a common king since 1380 (with interruptions).', 1450, 8, 29, NULL, NULL, NULL, 'day', '29 August 1450', 30, 'https://en.wikipedia.org/wiki/Treaty_of_Bergen'),
  ('Q10684373', 'Svante Nilsson Sture''s War against Denmark', 'The Dano-Swedish War from 1501 to 1512 was a military conflict between Denmark and Sweden within the Kalmar Union. The war began with a Swedish and a Norwegian revolt against King Hans and the siege of Queen Christina in her castle in Danish-held Stockholm.', 1501, NULL, NULL, 1512, NULL, NULL, 'year', '1501–1512', 45, 'https://en.wikipedia.org/wiki/Dano-Swedish_War_(1501%E2%80%931512)'),
  ('Q951270', 'Battle of Kringen', 'Battle of Kringen (Norwegian: Slaget ved Kringen) involved an ambush by Norwegian peasant militia of Scottish mercenary soldiers who were on their way to enlist in the Swedish army for the Kalmar War. The battle has since become a part of folklore in Norway, giving names to local places in the Ottadalen valley.', 1612, 8, 26, NULL, NULL, NULL, 'day', '26 August 1612', 47, 'https://en.wikipedia.org/wiki/Battle_of_Kringen'),
  ('Q1501750', 'Battle of Vågen', 'The Battle of Vågen was a naval battle between a Dutch merchant and treasure fleet and an English flotilla of warships on 2 August 1665 as part of the Second Anglo-Dutch War. The battle took place in Vågen (meaning "the bay, voe" in Norwegian), the main port area of neutral Bergen, Norway.', 1665, 8, 2, NULL, NULL, NULL, 'day', '2 August 1665', 50, 'https://en.wikipedia.org/wiki/Battle_of_V%C3%A5gen'),
  ('Q2815407', 'Siege of Fredriksten', 'The siege of Fredriksten (Norwegian: Beleiringen av Fredriksten festning) was an attack on the Norwegian fortress of Fredriksten in the city of Fredrikshald (now Halden) by King Charles XII of Sweden. While inspecting his troops'' lines, Charles XII was killed by a projectile.', 1718, 11, 30, 1718, 12, 14, 'day', '30 November 1718 – 14 December 1718', 43, 'https://en.wikipedia.org/wiki/Siege_of_Fredriksten'),
  ('Q48551', 'Lapp Codicil of 1751', 'Lapp Codicil of 1751 is an addendum to the Strömstad Treaty of 1751 that defined the Norwegian-Swedish border. It consists of 30 sections.', 1751, 10, 2, NULL, NULL, NULL, 'day', '2 October 1751', 43, 'https://en.wikipedia.org/wiki/Lapp_Codicil_of_1751'),
  ('Q2887830', 'Battle of Alvøen', 'The Battle of Alvøen was fought on 16 May 1808 between the British frigate HMS Tartar and five Norwegian gunboats off Bergen as part of the Gunboat War. Beginning in 1807, the Royal Navy had implemented a blockade of the Norwegian coast, leading to major sociopolitical turmoil in Norway since it was dependent on imports of foodstuffs from Denmark.', 1808, 5, 16, NULL, NULL, NULL, 'day', '16 May 1808', 37, 'https://en.wikipedia.org/wiki/Battle_of_Alv%C3%B8en'),
  ('Q2266114', 'Battle of Lyngør', 'The Battle of Lyngør was fought on 6 July 1812 between the British and Dano-Norwegian navies as part of the Gunboat War. A British squadron of one ship of the line and three brig-sloops under James Stewart located the Dano-Norwegian frigate Najaden sheltering off Lyngør, and engaged and destroyed her in a fierce engagement; Najaden''s captain Hans Peter Holm was wounded but survived, but 133 of his crew were killed and a further 87 wounded.', 1812, 7, 6, NULL, NULL, NULL, 'day', '6 July 1812', 41, 'https://en.wikipedia.org/wiki/Battle_of_Lyng%C3%B8r'),
  ('Q33773', 'Convention of Moss', 'The Convention of Moss (Mossekonvensjonen) was a ceasefire agreement signed on 14 August 1814 between the King of Sweden and the Norwegian government. It followed the Swedish-Norwegian War due to Norway''s claim to sovereignty.', 1814, 8, 14, NULL, NULL, NULL, 'day', '14 August 1814', 57, 'https://en.wikipedia.org/wiki/Convention_of_Moss'),
  ('Q1267717', 'Battle of Langnes', 'The Battle of Langnes, or the Battle of Langnes Entrenchment, was fought between Norway and Sweden as a part of the Swedish-Norwegian War of 1814. The battle, even as it ended inconclusively, served as a tactical victory to the Norwegians since they now could avoid an unconditional surrender to the Swedish.', 1814, 8, 9, NULL, NULL, NULL, 'day', '9 August 1814', 37, 'https://en.wikipedia.org/wiki/Battle_of_Langnes'),
  ('Q4587925', 'Battle of Matrand', 'The Battle of Matrand (Norwegian: Slaget ved Matrand) was a military battle on 5 August 1814 between Norwegian and Swedish forces as part of the Swedish-Norwegian War of 1814. The battle took place near the villages of Matrand and Skotterud in Eidskog.', 1814, 8, 5, NULL, NULL, NULL, 'day', '5 August 1814', 37, 'https://en.wikipedia.org/wiki/Battle_of_Matrand'),
  ('Q3274081', 'Kautokeino rebellion', 'The Sámi revolt in Guovdageaidnu, also known as the Kautokeino uprising, was a revolt in the village of Kautokeino in Kautokeino Municipality in northern Norway in 8th November 1852 by a group of Sámi who attacked representatives of the Norwegian authorities and other locals. The rebels killed the local merchant and the local lensmann, whipped their servants, town residents and the village priest, and burned down the merchant''s house.', 1852, 11, 8, NULL, NULL, NULL, 'day', '8 November 1852', 56, 'https://en.wikipedia.org/wiki/Kautokeino_rebellion'),
  ('Q1771974', 'Norwegian union dissolution referendum', 'A referendum on dissolving the union with Sweden was held in Norway on 13 August 1905. Voters were asked whether they endorsed the Storting''s declaration of 7 June that the personal union, in place since 1814, had ceased to exist.', 1905, 8, 13, NULL, NULL, NULL, 'day', '13 August 1905', 48, 'https://en.wikipedia.org/wiki/1905_Norwegian_union_dissolution_referendum'),
  ('Q6514328', 'Norwegian monarchy plebiscite', 'A referendum regarding the choice of the new monarch was held in Norway on 12 and 13 November 1905. Voters were asked whether they approved of the Storting''s decision to authorise the government to make the offer of the throne of the newly self-ruling country.', 1905, 11, 13, NULL, NULL, NULL, 'day', '13 November 1905', 48, 'https://en.wikipedia.org/wiki/1905_Norwegian_monarchy_referendum'),
  ('Q3440494', 'Norwegian prohibition referendum', 'A referendum on introducing prohibition was held in Norway on 5 and 6 October 1919. Partial prohibition had been in effect since 1917, and the prohibition proposal did not include all types of alcohol, only spirits.', 1919, 10, 6, NULL, NULL, NULL, 'day', '6 October 1919', 37, 'https://en.wikipedia.org/wiki/1919_Norwegian_prohibition_referendum'),
  ('Q461891', 'Svalbard Treaty', 'The Svalbard Treaty (originally the Spitsbergen Treaty) recognises the sovereignty of Norway over the Arctic archipelago of Svalbard, at the time called Spitsbergen. The exercise of sovereignty is, however, subject to certain stipulations, and not all Norwegian law applies.', 1920, 2, 9, NULL, NULL, NULL, 'day', '9 February 1920', 72, 'https://en.wikipedia.org/wiki/Svalbard_Treaty'),
  ('Q3440526', 'Norwegian continued prohibition referendum', 'A consultative and facultative referendum on continuing with prohibition was held in Norway on 18 October 1926. Partial prohibition had been effective since 1917, and following a 1919 referendum, spirits and dessert wine had also been banned.', 1926, 10, 18, NULL, NULL, NULL, 'day', '18 October 1926', 34, 'https://en.wikipedia.org/wiki/1926_Norwegian_continued_prohibition_referendum'),
  ('Q3391082', 'Oslo Agreements', 'The Oslo Agreements or Convention of Economic Rapprochement of 22 December 1930 were an economic agreement between the countries which had already agreed upon the Dutch-Scandinavian Economic Pact (Netherlands, Denmark, Norway, and Sweden) earlier that year and the countries of the BLEU, Belgium and Luxembourg. Finland would join the agreement in 1933.', 1930, 12, NULL, NULL, NULL, NULL, 'month', 'December 1930', 34, 'https://en.wikipedia.org/wiki/Oslo_Agreements%2C_1930'),
  ('Q150939', 'Operation Weserübung', 'Operation Weserübung (Unternehmen Weserübung [ˈveːzɐˌʔyːbʊŋ], (German: "Operation Weser Exercise") was the invasion of Denmark and Norway by Nazi Germany during World War II. Taking place from 9 April – 10 June 1940, it was the opening operation of the Norwegian Campaign. In the early morning of 9 April 1940 (Wesertag, "Weser Day"), German forces occupied Denmark and invaded Norway, ostensibly as a preventive manoeuvre against a planned Anglo-French occupation of Norway known as Plan R 4, which developed as a response to a German invasion of Norwegian territory.', 1940, NULL, NULL, 1940, 6, 10, 'year', '1940', 75, 'https://en.wikipedia.org/wiki/Operation_Weser%C3%BCbung'),
  ('Q177283', 'Altmark Incident', 'The Altmark incident (Norwegian: Altmark-affæren; German: Altmark-Zwischenfall) was a naval incident of World War II between British destroyers and the German tanker Altmark, which happened on 16–17 February 1940. It took place in what were neutral Norwegian waters.', 1940, 2, 16, NULL, NULL, NULL, 'day', '16 February 1940', 61, 'https://en.wikipedia.org/wiki/Altmark_incident'),
  ('Q567787', 'Battle of Drøbak Sound', 'The Battle of Drøbak Sound took place in Drøbak Sound, the northernmost part of the outer Oslofjord in south-eastern Norway, on 9 April 1940. It marked the end of the "Phoney War" and the beginning of active combat in World War II in Western Europe.', 1940, 4, 9, NULL, NULL, NULL, 'day', '9 April 1940', 50, 'https://en.wikipedia.org/wiki/Battle_of_Dr%C3%B8bak_Sound'),
  ('Q708217', 'Battles of Narvik', 'The Battles of Narvik were fought from 9 April to 8 June 1940, as a naval battle in Ofotfjord and as a land battle in the mountains surrounding the north Norwegian town of Narvik, as part of the Norwegian campaign of the Second World War. The two naval battles in Ofotfjord on 10 April and 13 April were fought between the British Royal Navy together with the Polish Navy (under British supreme command) and the German Kriegsmarine, while the two-month land campaign was fought by Norwegian, French, British, and Polish troops against German mountain troops, shipwrecked Kriegsmarine sailors, and…', 1940, 4, 9, 1940, 6, 8, 'day', '9 April 1940 – 8 June 1940', 64, 'https://en.wikipedia.org/wiki/Battles_of_Narvik'),
  ('Q1061048', 'Battle of Midtskogen', 'The Battle of Midtskogen was a minor battle fought on the night of 9–10 April 1940 during the Second World War between a German raiding party and an improvised Norwegian force. The site of the battle was Midtskogen Farm, approximately 5 km (3.1 mi) west of the town of Elverum at the mouth of the Østerdalen valley in southern Norway.', 1940, 4, 10, NULL, NULL, NULL, 'day', '10 April 1940', 39, 'https://en.wikipedia.org/wiki/Battle_of_Midtskogen'),
  ('Q1764599', 'Action off Lofoten', 'The action off Lofoten was a naval battle fought between the German Kriegsmarine and the British Royal Navy off the southern coast of the Lofoten Islands, Norway during the Second World War. A German squadron under Vizeadmiral Günther Lütjens consisting of the battleships Scharnhorst and Gneisenau met and engaged a British squadron under Admiral Sir William Whitworth consisting of the battlecruiser HMS Renown and nine destroyers.', 1940, 4, 9, NULL, NULL, NULL, 'day', '9 April 1940', 37, 'https://en.wikipedia.org/wiki/Action_off_Lofoten'),
  ('Q1800260', 'Battle of Dombås', 'The Battle of Dombås was fought between Norwegian Army infantry forces and German Fallschirmjäger paratroops in mid-April 1940. As part of their conquest of Norway south of Trondheim, and as a countermeasure against reported Allied landings in the Romsdal area of south-western Norway, the Germans dropped a company of paratroopers near the vital railroad junction of Dombås on 14 April 1940.', 1940, 4, 14, 1940, 4, 19, 'day', '14 April 1940 – 19 April 1940', 39, 'https://en.wikipedia.org/wiki/Battle_of_Domb%C3%A5s'),
  ('Q2890351', 'Battle of Vinjesvingen', 'The Battle of Vinjesvingen was a battle of the Norwegian campaign and took place in May 1940 in the Telemark county, Norway. It became one of the two last strongholds of Norwegian resistance in southern Norway during World War II, the other being Hegra Fortress.', 1940, 5, 3, 1940, 5, 5, 'day', '3 May 1940 – 5 May 1940', 39, 'https://en.wikipedia.org/wiki/Battle_of_Vinjesvingen'),
  ('Q3535001', 'Åndalsnes landings', 'The Åndalsnes landings were a British military operation in 1940, during the Norwegian Campaign of World War II. Following the German invasion of Norway in April 1940, a British Army expeditionary force was landed at Åndalsnes, in Romsdal, to support Norwegian Army units defending the city of Trondheim. British forces were also landed at Namsos, north of Åndalsnes, in a complementary pincer movement.', 1940, 4, NULL, 1940, 5, NULL, 'month', 'April 1940 – May 1940', 34, 'https://en.wikipedia.org/wiki/%C3%85ndalsnes_landings'),
  ('Q5084679', 'Norwegian Campaign', 'The Norwegian campaign (8 April – 10 June 1940) involved the attempt by Allied forces to defend northern Norway coupled with the Norwegian military''s resistance to the country''s invasion by Nazi Germany in World War II. Planned as Operation Wilfred and Plan R 4, while the German attack was feared but had not yet happened, the battlecruiser HMS Renown set out from Scapa Flow for Vestfjorden with twelve destroyers on 4 April. The Royal Navy and the Kriegsmarine met at the first and second naval battles of Narvik on 10 and 13 April, and British forces conducted the Åndalsnes landings on 13 April.', 1940, 4, 9, 1940, 6, 10, 'day', '9 April 1940 – 10 June 1940', 67, 'https://en.wikipedia.org/wiki/Norwegian_campaign'),
  ('Q61946821', 'Beisfjord massacre', 'The Beisfjord massacre (Norwegian: Beisfjord-massakren) was a massacre on 18 July 1942 at Beisfjord Camp No. 1 (German: Lager I Beisfjord; Norwegian: Beisfjord fangeleir) in the village of Beisfjord in Narvik Municipality, Norway of 288 political prisoners.', 1942, 7, 18, NULL, NULL, NULL, 'day', '18 July 1942', 34, 'https://en.wikipedia.org/wiki/Beisfjord_massacre'),
  ('Q715886', 'Battle of the North Cape', 'The Battle of the North Cape was a Second World War naval battle on 26 December 1943, part of the Arctic campaign. The German battleship Scharnhorst sailed to implement Operation Ostfront, an attack on Arctic convoys carrying supplies from the western Allies to the Soviet Union.', 1943, 12, 26, NULL, NULL, NULL, 'day', '26 December 1943', 61, 'https://en.wikipedia.org/wiki/Battle_of_the_North_Cape'),
  ('Q16470', 'Normandy landings', 'The Normandy landings were the landing operations and associated airborne operations on 6 June 1944 of the Allied invasion of Normandy in Operation Overlord during the Second World War. Codenamed Operation Neptune and often referred to as D-Day (after the military term), it is the largest seaborne invasion in history.', 1944, 6, 6, 1944, 8, 29, 'day', '6 June 1944 – 29 August 1944', 81, 'https://en.wikipedia.org/wiki/Normandy_landings'),
  ('Q705222', 'Petsamo–Kirkenes Offensive', 'The Petsamo–Kirkenes offensive was a major military offensive during World War II, mounted by the Red Army against the Wehrmacht in 1944 in the Petsamo region, ceded to the Soviet Union by Finland in accordance with the Moscow Armistice, and Norway. The offensive defeated the Wehrmacht''s forces in the Arctic, driving them back into Norway, and was called the "Tenth Shock" by Stalin.', 1944, 10, 7, 1944, 10, 31, 'day', '7 October 1944 – 31 October 1944', 60, 'https://en.wikipedia.org/wiki/Petsamo%E2%80%93Kirkenes_offensive'),
  ('Q2748375', 'Black Friday', 'On 9 February 1945, near the end of the Second World War, a force of Allied Bristol Beaufighter aircraft suffered many losses during an attack on the German destroyer Z33 and its escorting vessels; the operation was called Black Friday by the survivors. The German ships were sheltering in a strong defensive position in the Førde Fjord in Sogn og Fjordane county, Norway, forcing the Allied aircraft to attack through massed anti-aircraft fire (FlaK).', 1945, 2, 9, NULL, NULL, NULL, 'day', '9 February 1945', 47, 'https://en.wikipedia.org/wiki/Black_Friday_(1945)'),
  ('Q6514477', 'Widerøe Flight 933', 'Widerøe Flight 933, also known as the Mehamn Accident (Norwegian: Mehamn-ulykken), was the crash of a de Havilland Canada DHC-6 Twin Otter operated by Norwegian airline Widerøe. The Twin Otter crashed into the Barents Sea off Gamvik, Norway on 11 March 1982 at 13:27, killing all 15 people on board.', 1982, 3, 11, NULL, NULL, NULL, 'day', '11 March 1982', 47, 'https://en.wikipedia.org/wiki/Wider%C3%B8e_Flight_933'),
  ('Q2662518', 'Vnukovo Airlines Flight 2801', 'Vnukovo Airlines Flight 2801 was an international charter flight from Vnukovo International Airport in Moscow, Russia, to Svalbard Airport on Spitsbergen, in the Norwegian archipelago of Svalbard. On 29 August 1996 at 10:22:23 CEST, a Tupolev Tu-154M operating this flight crashed into the ground in Operafjellet during the final approach to Svalbard Airport.', 1996, 8, 29, NULL, NULL, NULL, 'day', '29 August 1996', 57, 'https://en.wikipedia.org/wiki/Vnukovo_Airlines_Flight_2801'),
  ('Q190029', 'Kosovo War', 'The Kosovo War (Albanian: Lufta e Kosovës; Serbian: Косовски рат, Kosovski rat) was an armed conflict in Kosovo that lasted from 28 February 1998 until 11 June 1999. It was fought between the forces of the Federal Republic of Yugoslavia (FRY), which controlled Kosovo before the war, and the Kosovo Albanian separatist militia known as the Kosovo Liberation Army (KLA).', 1998, 2, NULL, 1999, 6, 11, 'month', 'February 1998 – 11 June 1999', 81, 'https://en.wikipedia.org/wiki/Kosovo_War'),
  ('Q182865', 'War in Afghanistan (2001–2021)', 'The war in Afghanistan was a prolonged armed conflict from 2001 to 2021. It began with an invasion by a United States–led coalition under the name Operation Enduring Freedom in response to the September 11 attacks (9/11) carried out by the Taliban-allied and Afghanistan-based al-Qaeda.', 2001, 10, 7, 2021, 8, 30, 'day', '7 October 2001 – 30 August 2021', 84, 'https://en.wikipedia.org/wiki/War_in_Afghanistan_(2001%E2%80%932021)'),
  ('Q545449', 'Iraq War', 'The Iraq War (Arabic: حرب العراق, romanized: ḥarb al-ʿirāq), also referred to as the Second Gulf War (Gulf War II), was a protracted armed conflict in Iraq from 2003 to 2011. It began in March 2003 with the invasion by a United States–led coalition, which resulted in the overthrow of the Ba''athist government of Saddam Hussein.', 2003, 3, 20, 2011, 12, 15, 'day', '20 March 2003 – 15 December 2011', 89, 'https://en.wikipedia.org/wiki/Iraq_War'),
  ('Q2822713', 'Atlantic Airways Flight 670', 'Atlantic Airways Flight 670 was a crash following a runway overrun of a British Aerospace 146-200A at 07:32 on 10 October 2006 at Stord Airport, Sørstokken, Norway. The aircraft''s spoilers failed to deploy, causing inefficient braking.', 2006, 10, 10, NULL, NULL, NULL, 'day', '10 October 2006', 52, 'https://en.wikipedia.org/wiki/Atlantic_Airways_Flight_670'),
  ('Q79967', '2011 Norway attacks', 'On 22 July 2011, 32-year-old far-right extremist Anders Behring Breivik committed two domestic terrorist attacks in Norway against the government, the civilian population, and a Workers'' Youth League (AUF) summer camp, in which a total of 77 people were killed. The first attack was a car bomb explosion in Oslo within Regjeringskvartalet, the executive government quarter of Norway, at 15:25:22 (CEST).', 2011, 7, 22, NULL, NULL, NULL, 'day', '22 July 2011', 85, 'https://en.wikipedia.org/wiki/2011_Norway_attacks'),
  ('Q66363708', 'Bærum mosque shooting', 'On 10 August 2019, the 21-year-old neo-Nazi Philip Manshaus murdered his 17-year-old adopted sister Johanne Zhangjia Ihle-Hansen at their home in Bærum, Akershus, Norway. He then drove to the Al-Noor Islamic Centre and broke into the building by shooting a glass door.', 2019, 8, 10, NULL, NULL, NULL, 'day', '10 August 2019', 43, 'https://en.wikipedia.org/wiki/2019_B%C3%A6rum_murder_and_mosque_attack'),
  ('Q81068910', 'COVID-19 pandemic', 'The global COVID-19 pandemic (also known as the coronavirus pandemic), caused by severe acute respiratory syndrome coronavirus 2 (SARS-CoV-2), began with an outbreak in Wuhan, China, in December 2019. It spread to other parts of Asia and then worldwide in early 2020.', 2019, 12, 1, NULL, NULL, NULL, 'day', '1 December 2019', 100, 'https://en.wikipedia.org/wiki/COVID-19_pandemic'),
  ('Q86458103', 'COVID-19 pandemic in Europe', 'The global COVID-19 pandemic arrived in Europe with its first confirmed case in Bordeaux, France, on 24 January 2020, and subsequently spread widely across the continent. By 17 March 2020, every country in Europe had confirmed a case, and all have reported at least one death, with the exception of Vatican City.', 2020, 1, 24, NULL, NULL, NULL, 'day', '24 January 2020', 65, 'https://en.wikipedia.org/wiki/COVID-19_pandemic_in_Europe'),
  ('Q112695273', '2022 Oslo shooting', 'The 2022 Oslo shooting, commonly known in Norway as the Pride Shooting in Oslo (Pride-skyting i Oslo), occurred on 25 June 2022, when two people were killed and twenty-one people were wounded in a mass shooting in Oslo, Norway. Police declared the incident as an "act of Islamist terrorism".', 2022, 6, 25, NULL, NULL, NULL, 'day', '25 June 2022', 63, 'https://en.wikipedia.org/wiki/2022_Oslo_shooting');
